// Reference decoder for the Mach-1-Ternary-35B packed format
// (SyzygyResearch/Mach-1-Ternary-35B).
//
// This is a line-for-line port of the pure-numpy executable spec that ships
// with the model (decode.py: _np_unpack_trellis / _np_full_lut / _np_recons /
// _np_hadamard / decode_trellis / _nell_bits_to_states / decode_ne_ll_tensor /
// decode_embed). Every f32 operation goes through Math.fround; for f32
// operands, +,-,*,/ computed in doubles and rounded to f32 are exactly the
// IEEE-754 binary32 results (p2 >= 2*p1+2), so this reference is bit-exact to
// the numpy decoder — verified by test/ against fixtures generated by
// decode.py itself. ONE exception: the demoted-expert basis residual is a
// numpy f32 BLAS matmul whose accumulation order is not reproducible; it is
// computed here in f64 and carries a tolerance contract, never bit-exactness.
//
// The WGSL kernels are validated against THIS module in the browser.

const fr = Math.fround;

// ---------------------------------------------------------------- fp16 spec
// decode.py rounds the reconstructed unit weights to fp16 (the qlstate's
// stored dtype) before scaling. Manual IEEE round-to-nearest-even f32->f16,
// then exact f16->f32 — no Float16Array dependency.
export function f16RoundBits(x) {
  const f32 = new Float32Array(1);
  const u32 = new Uint32Array(f32.buffer);
  f32[0] = x;
  const u = u32[0];
  const sign = (u >>> 16) & 0x8000;
  const a = u & 0x7fffffff;
  if (a >= 0x47800000) {                       // overflow -> inf (nan keeps mantissa bit)
    return a > 0x7f800000 ? sign | 0x7e00 : sign | 0x7c00;
  }
  if (a < 0x38800000) {                        // f16-subnormal range (incl. f32 subnormals)
    // q = round(m32 * 2^(e-126)): the 24-bit significand lands on the f16
    // subnormal grid (units of 2^-24) after a right shift of 126 - e.
    const shift = 126 - (a >>> 23);
    if (shift > 24) return sign;               // < 2^-25 with no possible tie -> 0
    const mant = (a & 0x7fffff) | 0x800000;
    const q = mant >>> shift;
    const rem = mant & ((1 << shift) - 1);
    const half = 1 << (shift - 1);
    let r = q;
    if (rem > half || (rem === half && (q & 1) === 1)) r += 1;
    return sign | r;                           // carry into exponent is correct
  }
  const e = ((a >>> 23) - 112) << 10;
  let h = sign | (e & 0x7c00) | ((a >>> 13) & 0x3ff);
  const rem = a & 0x1fff;
  if (rem > 0x1000 || (rem === 0x1000 && (h & 1) === 1)) h += 1;
  return h;
}

export function f16ToF32(h) {
  const s = (h & 0x8000) ? -1 : 1;
  const e = (h >>> 10) & 0x1f;
  const m = h & 0x3ff;
  if (e === 0) return fr(s * m * 2 ** -24);      // exact: integer * power of two
  if (e === 31) return m ? NaN : s * Infinity;
  return fr(s * (m + 1024) * 2 ** (e - 25));     // exact
}

export const f16Round = (x) => f16ToF32(f16RoundBits(x));

// ------------------------------------------------------- trellis unpacking
// Bitstream per tile: T*K bits packed MSB-first into big-endian u16 words.
// The register is a sliding L-bit window at offset j*(K*V), tail-biting.
export function unpackStates(words, tileBase, wordsPerTile, params) {
  const { L, K, V, td_x, td_y } = params;
  const T = td_x * td_y;
  const step = K * V;                     // whole by format contract
  const nbits = T * K;
  const nstep = T / V;
  const states = new Int32Array(nstep);
  const bit = (pos) => {
    if (pos >= nbits) pos -= nbits;       // tail-biting wrap
    return (words[tileBase + (pos >>> 4)] >>> (15 - (pos & 15))) & 1;
  };
  for (let j = 0; j < nstep; j++) {
    let s = 0;
    const start = j * step;
    for (let b = 0; b < L; b++) s = (s << 1) | bit(start + b);
    states[j] = s;
  }
  return states;
}

// ------------------------------------------------- hashed symmetric LUT
// row(s) = (s*(s+1) >> (16 - tlut_bits - 1)) & (2^tlut_bits - 1)
// component 0 negated iff bit 15 of s*(s+1). s*(s+1) < 2^32: exact in u32.
export function lutRowSign(s, tlutBits) {
  const p = (s * (s + 1)) >>> 0;          // exact for s < 2^16
  const shift = 16 - tlutBits - 1;
  const row = (p >>> shift) & ((1 << tlutBits) - 1);
  const neg = (p >>> 15) & 1;
  return [row, neg];
}

// ------------------------------------------------------------- Hadamard
// Orthonormal FWHT along contiguous vectors of length dim (power of two),
// exact op order of decode.py: butterflies at span 1,2,4..., one final f32
// division by f32(sqrt(f32(dim))).
export function fwhtRows(data, rows, dim) {
  const sqrtDim = fr(Math.sqrt(fr(dim)));
  for (let r = 0; r < rows; r++) {
    const base = r * dim;
    for (let span = 1; span < dim; span *= 2) {
      const stride = 2 * span;
      for (let b = 0; b < dim; b += stride) {
        for (let k = 0; k < span; k++) {
          const i = base + b + k;
          const a = data[i], c = data[i + span];
          data[i] = fr(a + c);
          data[i + span] = fr(a - c);
        }
      }
    }
    for (let i = base; i < base + dim; i++) data[i] = fr(data[i] / sqrtDim);
  }
}

// ------------------------------------------------------------ full decode
// W = diag(sv) . H_m . (f16(unit) [* wscale]) . H_n . diag(su), [m0, n0] f32.
// trellisWords: Uint16Array [ntiles * wordsPerTile]; tlut: Float32Array
// [2^tlut_bits * V] (F32 Lloyd book — the fp16 spec-round is REAL here);
// su: len n0, sv: len m0 (±1 for demoted experts, continuous fp16 for kept).
// wscale: scalar for demoted experts, null/undefined for kept (absorbed in
// sv) — multiplying by exact 1.0 is a bit-level identity, matching
// decode.py's wscale=None skip.
export function decodeTrellis(trellisWords, su, sv, tlut, m0, n0, params, wscale) {
  if (wscale === null || wscale === undefined) wscale = 1.0;
  const { V, td_x, td_y, tlut_bits } = params;
  const T = td_x * td_y;
  const nstep = T / V;
  const ntx = m0 / td_x, nty = n0 / td_y;
  const ntiles = ntx * nty;
  const wordsPerTile = (T * params.K) / 16;
  if (trellisWords.length !== ntiles * wordsPerTile) {
    throw new Error(`trellis length ${trellisWords.length} != ${ntiles * wordsPerTile}`);
  }
  const W = new Float32Array(m0 * n0);
  for (let t = 0; t < ntiles; t++) {
    const ti = Math.floor(t / nty), tj = t % nty;
    const states = unpackStates(trellisWords, t * wordsPerTile, wordsPerTile, params);
    for (let j = 0; j < nstep; j++) {
      const [row, neg] = lutRowSign(states[j], tlut_bits);
      for (let v = 0; v < V; v++) {
        let val = tlut[row * V + v];
        if (v === 0 && neg) val = -val;
        const idx = j * V + v;                       // scalar index inside tile
        const rr = ti * td_x + (idx >> 4);
        const cc = tj * td_y + (idx & 15);
        // fp16 spec round, then wscale in f32 (decode.py op order)
        W[rr * n0 + cc] = fr(f16Round(val) * wscale);
      }
    }
  }
  // rowside = H_n(rows) * su
  fwhtRows(W, m0, n0);
  for (let r = 0; r < m0; r++) {
    for (let c = 0; c < n0; c++) W[r * n0 + c] = fr(W[r * n0 + c] * su[c]);
  }
  // colside = H_m(cols) * sv  (operate on the transpose, same arithmetic)
  const Wt = new Float32Array(n0 * m0);
  for (let r = 0; r < m0; r++) {
    for (let c = 0; c < n0; c++) Wt[c * m0 + r] = W[r * n0 + c];
  }
  fwhtRows(Wt, n0, m0);
  for (let c = 0; c < n0; c++) {
    for (let r = 0; r < m0; r++) Wt[c * m0 + r] = fr(Wt[c * m0 + r] * sv[r]);
  }
  for (let r = 0; r < m0; r++) {
    for (let c = 0; c < n0; c++) W[r * n0 + c] = Wt[c * m0 + r];
  }
  return W;
}

// -------------------------------------- v3t trained-container expert decode
// decode.py decode_expert_v3t (Mach-1-Ternary-Additive-35B): NO wscale (it is
// absorbed into continuous fp16 sv), and each 16x16 tile of the fp16-cast
// unit matrix is multiplied by gamma[waveIndex(tile)] in f32 BEFORE the two
// Hadamards. gamma ships fp16 [Mb+Nb] per (expert, proj); the wave index is
// the encoder's anti-diagonal starts recurrence — the LAST wavefront that
// wrote each tile, including the reference schedule's duplicated
// top-right-starting wave. Ported verbatim from decode.py wave_index_map.
export function waveIndexMap(Mb, Nb) {
  const starts = [];
  for (let i = 0; i < Mb; i++) starts.push([Mb - i - 1, Nb - 1]);
  for (let i = 0; i < Nb; i++) starts.push([0, Nb - i - 1]);
  const idx = new Uint32Array(Mb * Nb);
  for (let w = 0; w < starts.length; w++) {
    let [jm, jn] = starts[w];
    while (jm >= 0 && jm < Mb && jn >= 0 && jn < Nb) {
      idx[jm * Nb + jn] = w;
      jm += 1;
      jn -= 1;
    }
  }
  return idx;
}

// W = diag(sv) . H_m . (gamma_tile * f16(unit)) . H_n . diag(su), [m0, n0].
// gamma: Float32Array [Mb+Nb] (f16 values exactly widened — f16->f32 is
// exact, and one f32 multiply matches numpy's apply_wave_gamma bit-for-bit).
export function decodeTrellisV3t(trellisWords, su, sv, gamma, tlut, m0, n0, params) {
  const { V, td_x, td_y, tlut_bits } = params;
  const T = td_x * td_y;
  const nstep = T / V;
  const ntx = m0 / td_x, nty = n0 / td_y;
  const ntiles = ntx * nty;
  const wordsPerTile = (T * params.K) / 16;
  if (trellisWords.length !== ntiles * wordsPerTile) {
    throw new Error(`trellis length ${trellisWords.length} != ${ntiles * wordsPerTile}`);
  }
  const widx = waveIndexMap(ntx, nty);
  const W = new Float32Array(m0 * n0);
  for (let t = 0; t < ntiles; t++) {
    const ti = Math.floor(t / nty), tj = t % nty;
    const g = gamma[widx[t]];
    const states = unpackStates(trellisWords, t * wordsPerTile, wordsPerTile, params);
    for (let j = 0; j < nstep; j++) {
      const [row, neg] = lutRowSign(states[j], tlut_bits);
      for (let v = 0; v < V; v++) {
        let val = tlut[row * V + v];
        if (v === 0 && neg) val = -val;
        const idx = j * V + v;
        const rr = ti * td_x + (idx >> 4);
        const cc = tj * td_y + (idx & 15);
        W[rr * n0 + cc] = fr(f16Round(val) * g);
      }
    }
  }
  fwhtRows(W, m0, n0);
  for (let r = 0; r < m0; r++) {
    for (let c = 0; c < n0; c++) W[r * n0 + c] = fr(W[r * n0 + c] * su[c]);
  }
  const Wt = new Float32Array(n0 * m0);
  for (let r = 0; r < m0; r++) {
    for (let c = 0; c < n0; c++) Wt[c * m0 + r] = W[r * n0 + c];
  }
  fwhtRows(Wt, n0, m0);
  for (let c = 0; c < n0; c++) {
    for (let r = 0; r < m0; r++) Wt[c * m0 + r] = fr(Wt[c * m0 + r] * sv[r]);
  }
  for (let r = 0; r < m0; r++) {
    for (let c = 0; c < n0; c++) W[r * n0 + c] = Wt[c * m0 + r];
  }
  return W;
}

// ---------------------------------------------- int5-g64 head tier (additive)
// decode.py decode_int5g64: symmetric int5 codes, 8 per 5 little-endian bytes
// (code i occupies bits [5i, 5i+5) of the 40-bit block; stored value q+16),
// one fp16 scale per 64 reduction-dim weights, RAW domain (no rotation).
// W[r, j] = f32(q) * f32(gscale[r, j/64]) — elementwise, BIT-EXACT tier.
export function decodeInt5g64(qp, gscale, m0, n0, group = 64) {
  const bytesPerRow = (n0 / 8) * 5;
  const ng = n0 / group;
  const W = new Float32Array(m0 * n0);
  for (let r = 0; r < m0; r++) {
    const rb = r * bytesPerRow;
    for (let j = 0; j < n0; j++) {
      const bitpos = (j % 8) * 5 + ((j >> 3) * 40);
      const byte = rb + (bitpos >> 3), off = bitpos & 7;
      const q = (((qp[byte] | ((qp[byte + 1] || 0) << 8)) >> off) & 31) - 16;
      W[r * n0 + j] = fr(q * gscale[r * ng + (j / group | 0)]);
    }
  }
  return W;
}

// ----------------------------------- lut4 embedding tier (additive, lossless)
// packed/ne/embed_packed.safetensors metadata: codes uint8 [rows, hid/2] with
// two nibbles per byte (LOW nibble = even column), lut bf16 [rows*ngroups, 16]
// (per-row per-group-of-128 16-entry table). bf16 -> f32 is an exact widen.
export const bf16ToF32 = (b) => {
  const buf = new ArrayBuffer(4);
  new Uint32Array(buf)[0] = b << 16;
  return new Float32Array(buf)[0];
};

export function decodeEmbedLut4Row(codes, lutBits, row, hid, group = 128) {
  const ng = hid / group;
  const out = new Float32Array(hid);
  const cb = row * (hid >> 1);
  const lb = row * ng * 16;
  for (let j = 0; j < hid; j++) {
    const byte = codes[cb + (j >> 1)];
    const code = (j & 1) ? (byte >> 4) : (byte & 15);
    out[j] = bf16ToF32(lutBits[lb + (j / group | 0) * 16 + code]);
  }
  return out;
}

// -------------------------------------------------- demoted-expert basis
// decode.py (decode_expert_layer): w += fp32(B * c[None, :]) @ fp32(A) for
// demoted experts when the manifest carries "basis". numpy's f32 BLAS
// accumulation order is not reproducible sequentially, so this residual is
// accumulated in f64 and the result carries a TOLERANCE contract (the
// trellis part of W stays bit-exact). A: [r, n0] , B: [m0, r], c: [r].
export function addBasisResidual(W, A, B, c, m0, n0, r) {
  for (let i = 0; i < m0; i++) {
    for (let j = 0; j < n0; j++) {
      let acc = 0;
      for (let k = 0; k < r; k++) acc += B[i * r + k] * c[k] * A[k * n0 + j];
      W[i * n0 + j] = fr(W[i * n0 + j] + fr(acc));
    }
  }
  return W;
}

// ------------------------------------------------ NE transform-free tier
// decode.py: _nell_bits_to_states + decode_ne_ll_tensor. Lloyd bitshift
// trellis: s_{-1} = 0; s_t = ((s_{t-1} << k) | b_t) & (2^L - 1) where b_t is
// the k NEW bits of step t, stored MSB-first, bytes big-endian (packbits).
// W[r, t] = f32(lut[s_t]) * f32(gscale[r, t/group]) — elementwise, exact
// order, so this tier is BIT-EXACT (unlike the basis residual).
export function neStates(packedRow, T, k, L = 12) {
  const mask = (1 << L) - 1;
  const states = new Int32Array(T);
  let s = 0;
  let pos = 0;
  for (let t = 0; t < T; t++) {
    let b = 0;
    for (let j = 0; j < k; j++, pos++) {
      b = (b << 1) | ((packedRow[pos >>> 3] >>> (7 - (pos & 7))) & 1);
    }
    s = ((s << k) | b) & mask;
    states[t] = s;
  }
  return states;
}

// packed: Uint8Array [B * T*k/8]; gscale: Float32Array [B * T/group] (from
// f16); lut: Float32Array [2^L] (from f16). Returns W [m0, n0] f32 in the
// ORIGINAL orientation (transposes back when the tensor was stored as W^T).
export function decodeNeTensor(packed, gscale, lut, m0, n0, k, transposed,
  { L = 12, group = 128 } = {}) {
  const B = transposed ? n0 : m0;
  const T = transposed ? m0 : n0;
  const rowBytes = (T * k) / 8;
  const ng = T / group;
  const S = new Float32Array(B * T);
  for (let r = 0; r < B; r++) {
    const states = neStates(packed.subarray(r * rowBytes, (r + 1) * rowBytes), T, k, L);
    for (let t = 0; t < T; t++) {
      S[r * T + t] = fr(lut[states[t]] * gscale[r * ng + ((t / group) | 0)]);
    }
  }
  if (!transposed) return S;
  const W = new Float32Array(m0 * n0);
  for (let r = 0; r < B; r++) {
    for (let t = 0; t < T; t++) W[t * n0 + r] = S[r * T + t];
  }
  return W;
}

// --------------------------------------------------- embed int3 asym tier
// decode.py::decode_embed: step = max(mx - mn, 1e-8) / (2^bits - 1) in f32,
// W = mn + q * step, all elementwise f32 — bit-exact. mn/mx: Float32Array
// [rows * hid/group] (from f16); qPacked: Uint8Array MSB-first packbits.
export function decodeEmbed(qPacked, mn, mx, rows, hid, bits = 3, group = 64) {
  const ng = hid / group;
  const lv = (1 << bits) - 1;
  const eps = fr(1e-8);
  const W = new Float32Array(rows * hid);
  const rowBytes = (hid * bits) / 8;
  for (let r = 0; r < rows; r++) {
    let pos = r * rowBytes * 8;
    for (let j = 0; j < hid; j++) {
      let q = 0;
      for (let b = 0; b < bits; b++, pos++) {
        q = (q << 1) | ((qPacked[pos >>> 3] >>> (7 - (pos & 7))) & 1);
      }
      const g = (j / group) | 0;
      const d = fr(mx[r * ng + g] - mn[r * ng + g]);
      const step = fr(Math.max(d, eps) / lv);
      W[r * hid + j] = fr(mn[r * ng + g] + fr(q * step));
    }
  }
  return W;
}

// f64-accumulated GEMV ground truth for tolerance checks of the fused kernel.
export function gemv64(W, x, m, n) {
  const y = new Float64Array(m);
  for (let r = 0; r < m; r++) {
    let acc = 0;
    const base = r * n;
    for (let c = 0; c < n; c++) acc += W[base + c] * x[c];
    y[r] = acc;
  }
  return y;
}

// ------------------------------------------------------------- synthetic
// Deterministic xorshift32 — same generator on the demo page and in tests.
export function makeRng(seed) {
  let s = seed >>> 0 || 1;
  return () => {
    s ^= s << 13; s >>>= 0;
    s ^= s >> 17;
    s ^= s << 5; s >>>= 0;
    return s / 4294967296;
  };
}

// Continuous Lloyd-like F32 codebook (the live book is F32, gpu_lloyd) —
// continuous values make the fp16 spec-round REAL, as in the release.
export function synthTlut(rng, rows, V, scale = 0.9) {
  const t = new Float32Array(rows * V);
  for (let i = 0; i < t.length; i++) t[i] = fr((rng() * 2 - 1) * scale * 1.7);
  return t;
}

// `demoted`: ±1 su/sv + scalar wscale (K1-population side-streams);
// otherwise continuous fp16-valued su/sv with wscale null (kept population).
export function synthCase(params, m0, n0, seed, demoted = false) {
  const rng = makeRng(seed);
  const T = params.td_x * params.td_y;
  const wordsPerTile = (T * params.K) / 16;
  const ntiles = (m0 / params.td_x) * (n0 / params.td_y);
  const trellis = new Uint16Array(ntiles * wordsPerTile);
  for (let i = 0; i < trellis.length; i++) trellis[i] = Math.floor(rng() * 65536);
  const tlut = synthTlut(rng, 1 << params.tlut_bits, params.V);
  const su = new Float32Array(n0), sv = new Float32Array(m0);
  if (demoted) {
    for (let i = 0; i < n0; i++) su[i] = rng() < 0.5 ? -1 : 1;
    for (let i = 0; i < m0; i++) sv[i] = rng() < 0.5 ? -1 : 1;
  } else {
    for (let i = 0; i < n0; i++) su[i] = f16Round((rng() * 2 - 1) * 0.1);
    for (let i = 0; i < m0; i++) sv[i] = f16Round((rng() * 2 - 1) * 0.1);
  }
  const x = new Float32Array(n0);
  for (let i = 0; i < n0; i++) x[i] = fr((rng() * 2 - 1) * 1.5);
  return { trellis, tlut, su, sv, x, wscale: demoted ? fr(0.02173) : null, m0, n0, params };
}

// Synthetic v3t (additive) expert: continuous fp16 su/sv, per-wave fp16 gamma.
export function synthCaseV3t(params, m0, n0, seed) {
  const rng = makeRng(seed);
  const T = params.td_x * params.td_y;
  const wordsPerTile = (T * params.K) / 16;
  const ntx = m0 / params.td_x, nty = n0 / params.td_y;
  const trellis = new Uint16Array(ntx * nty * wordsPerTile);
  for (let i = 0; i < trellis.length; i++) trellis[i] = Math.floor(rng() * 65536);
  const tlut = synthTlut(rng, 1 << params.tlut_bits, params.V);
  const su = new Float32Array(n0), sv = new Float32Array(m0);
  for (let i = 0; i < n0; i++) su[i] = f16Round((rng() * 2 - 1) * 0.1);
  for (let i = 0; i < m0; i++) sv[i] = f16Round((rng() * 2 - 1) * 0.1);
  const gamma = new Float32Array(ntx + nty);
  for (let i = 0; i < gamma.length; i++) gamma[i] = f16Round(0.6 + rng() * 0.9);
  const x = new Float32Array(n0);
  for (let i = 0; i < n0; i++) x[i] = fr((rng() * 2 - 1) * 1.5);
  return { trellis, tlut, su, sv, gamma, x, m0, n0, params };
}

// Synthetic int5-g64 head tensor.
export function synthInt5Case(m0, n0, seed, group = 64) {
  const rng = makeRng(seed);
  const qp = new Uint8Array(m0 * (n0 / 8) * 5);
  for (let i = 0; i < qp.length; i++) qp[i] = Math.floor(rng() * 256);
  const gscale = new Float32Array(m0 * (n0 / group));
  for (let i = 0; i < gscale.length; i++) gscale[i] = f16Round(0.002 + rng() * 0.03);
  const x = new Float32Array(n0);
  for (let i = 0; i < n0; i++) x[i] = fr((rng() * 2 - 1) * 1.5);
  return { qp, gscale, x, m0, n0, group };
}

// Synthetic NE tensor (non-transposed) matching the live tier layout.
export function synthNeCase(m0, n0, k, seed, { L = 12, group = 128 } = {}) {
  const rng = makeRng(seed);
  const packed = new Uint8Array((m0 * n0 * k) / 8);
  for (let i = 0; i < packed.length; i++) packed[i] = Math.floor(rng() * 256);
  const gscale = new Float32Array(m0 * (n0 / group));
  for (let i = 0; i < gscale.length; i++) gscale[i] = f16Round(0.005 + rng() * 0.05);
  const lut = new Float32Array(1 << L);
  for (let i = 0; i < lut.length; i++) lut[i] = f16Round((rng() * 2 - 1) * 1.4);
  const x = new Float32Array(n0);
  for (let i = 0; i < n0; i++) x[i] = fr((rng() * 2 - 1) * 1.5);
  return { packed, gscale, lut, x, m0, n0, k, L, group };
}

// Codec parameter sets of the shipped release (live shard manifests,
// SyzygyResearch/Mach-1-Ternary-35B; cb1 == cb2 — the demoted population
// differs only in side-streams, not rate).
export const CB_EXPERT = { K: 1.375, L: 16, V: 8, tlut_bits: 15, td_x: 16, td_y: 16 };
// Mach-1-Ternary-Additive-35B trained container (decode.py CB_V3T).
export const CB_EXPERT_V3T = { K: 1.5, L: 16, V: 8, tlut_bits: 15, td_x: 16, td_y: 16 };
// Mach-1-Ternary-Additive-35B NE spine (decode.py decode_ne_shard_canon,
// codec "canon_rht_bitshift_trellis_intlattice"). Same two-sided-RHT trellis
// as the demoted experts — int8 SU/SV + scalar Wscale — so plain
// decodeTrellis() decodes it; only the rate params differ. The codebook is
// tier-shared (packed/ne/tlut.safetensors, F32 [512, 2]).
export const CB_NE_CANON = { K: 4, L: 16, V: 2, tlut_bits: 9, td_x: 16, td_y: 16 };
export const NE_LAYER = { k: 4, L: 12, group: 128 };   // packed/ne/L*.safetensors
export const NE_HEAD = { k: 3, L: 12, group: 128 };    // packed/ne/head_c*of8

// ------------------------------------------------------------------------
// int4 codebook packing (additive release only).
//
// The additive expert alphabet is an exact scaled integer lattice: 10 levels,
// step * {-5..4} (verified against the live codebook.safetensors — 32768x8,
// step 0.8963924050331116, max lattice error 2e-7). Ten levels fit a nibble,
// so an 8-value row packs into ONE u32 (4 B) instead of 8 f16 (16 B): the
// table drops 512 KB -> 128 KB and the kernel's random codebook gather — its
// hot spot — reads 4x fewer bytes. Returns null when the alphabet is not an
// exact lattice or needs more than 16 levels, so callers fall back safely.
// ------------------------------------------------------------------------
// Bit-plane form of the int4 lattice table, for the multiply-free kernel:
// each V=8 codebook row becomes four 8-bit masks in one u32 —
//   bits  0..7   sign of level v        (1 = negative)
//   bits  8..15  bit 0 of |level v|
//   bits 16..23  bit 1 of |level v|
//   bits 24..31  bit 2 of |level v|     (|level| <= 5 needs 3 planes)
// The row's dot product then factors as A0 + 2*A1 + 4*A2 with each A_p a
// sign-selected SUM of x values — the per-weight shift-add decomposition
// becomes one doubling per plane per state. The trellis sign (component 0
// negated when bit 15 of s(s+1) is set) is `signMask ^ rn.y` in-kernel.
export function buildPlaneTlut(int4) {
  if (!int4 || Math.max(...int4.ints.map(Math.abs)) > 7) return null;
  const rows = int4.packed.length;
  const packed = new Uint32Array(rows);
  for (let r = 0; r < rows; r++) {
    const w = int4.packed[r];
    let m = 0;
    for (let v = 0; v < 8; v++) {
      const lvl = int4.ints[(w >>> (4 * v)) & 0xf] | 0;
      const mm = Math.abs(lvl);
      if (lvl < 0) m |= 1 << v;
      if (mm & 1) m |= 1 << (8 + v);
      if (mm & 2) m |= 1 << (16 + v);
      if (mm & 4) m |= 1 << (24 + v);
    }
    packed[r] = m >>> 0;
  }
  return { packed, step: int4.step };
}

export function buildInt4Tlut(tlut, V = 8, { maxAbs = 5 } = {}) {
  const uniq = [...new Set(tlut)].sort((a, b) => a - b);
  if (uniq.length > 16) return null;
  const nz = uniq.filter((v) => v !== 0).map(Math.abs).sort((a, b) => a - b);
  if (!nz.length) return null;
  const step = nz[0];
  const ints = uniq.map((v) => Math.round(v / step));
  const err = Math.max(...uniq.map((v, i) => Math.abs(v / step - ints[i])));
  if (!(err < 1e-5)) return null;                       // not an integer lattice
  if (Math.max(...ints.map(Math.abs)) > maxAbs) return null;
  const idxOf = new Map(uniq.map((v, i) => [v, i]));
  const rows = tlut.length / V;
  const packed = new Uint32Array(rows);
  for (let r = 0; r < rows; r++) {
    let w = 0;
    for (let v = 0; v < V; v++) w |= idxOf.get(tlut[r * V + v]) << (4 * v);
    packed[r] = w >>> 0;
  }
  return { packed, ints, step, levels: uniq.length, latticeErr: err };
}
